compile.workshop:
variables {
    global:
        0: a
        1: __d
        2: e
        4: c
        126: __f___
        127: __b__
    player:
        0: pa
        1: pd
        3: pc
        127: __pb__
}

//Optimize for size enabled
rule ("Clear tri­gger a­dmin") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    actions {
        Set Global Variable(a, Remove From Array(Global.e, 1));
        Set Global Variable(a, Global.e);
        Set Global Variable(e, Char In String(Empty Array, False));
        Set Global Variable(a, Add(Left, Forward));
        Set Global Variable(a, Multiply(255, Left));
        Set Global Variable(a, Backward);
        Set Player Variable(Event Player, pa, 1);
        Set Player Variable(Event Player, __pb__, 1);
        Set Player Variable(Event Player, pc, 1);
        Set Player Variable(Event Player, pd, 1);
        Set Global Variable(__b__, 1);
        Set Global Variable(__d, 1);
        Set Global Variable(__f___, 1);
        Set Global Variable(c, 1);
    }
}

